def first_sentence(text: str) -> str:
    """Keep workarounds to one sentence. Also drops the junk Gemini sometimes glues on with no
    spaces (e.g. "settings.functionality.text.word.count.check:11...")."""
    junk = re.search(r"\S{40,}", text)
